Read the cached values from `RS.Food`, keep rows 6–607 with a non-empty Item Class in column I, and group them by that class. Sort each group by Net Sales in column B descending, breaking ties by row order, then assign sequential ranks 1..n. Write those integer ranks into `K6:K607`, leaving rows without an Item Class empty.

```python
import shutil
import openpyxl
from collections import Counter

shutil.copy(INIT, OUT)

SHEET = "RS.Food"
FIRST_ROW = 6
LAST_ROW = 607

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals[SHEET] if SHEET in vals.sheetnames else None
ws = wb[SHEET] if SHEET in wb.sheetnames else wb.create_sheet(SHEET)

def to_number(x):
    if x is None:
        return 0.0
    if isinstance(x, bool):
        return float(x)
    if isinstance(x, (int, float)):
        v = float(x)
        return 0.0 if v != v else v
    try:
        v = float(str(x).strip())
        return 0.0 if v != v else v
    except Exception:
        return 0.0

records = []
if vws is not None:
    for r in range(FIRST_ROW, LAST_ROW + 1):
        i_val = vws.cell(row=r, column=9).value  # Column I: Item Class
        if i_val is None:
            continue
        if isinstance(i_val, str) and i_val.strip() == "":
            continue

        b_val = vws.cell(row=r, column=2).value  # Column B: Net Sales
        records.append((r, str(i_val).strip(), to_number(b_val)))

groups = {}
for r, cls, b in records:
    groups.setdefault(cls, []).append((r, b))

ranks = {}
for cls, items in groups.items():
    # Descending Net Sales; ties broken by original row order.
    items.sort(key=lambda item: (-item[1], item[0]))
    for rank, (r, _) in enumerate(items, start=1):
        ranks[r] = rank

for r in range(FIRST_ROW, LAST_ROW + 1):
    ws.cell(row=r, column=11).value = ranks.get(r)  # Column K: Category Rank

wb.save(OUT)

print("ranked_rows", len(ranks))
for r in sorted(ranks)[:10]:
    print("sample", r, ranks[r])

for cls in sorted(groups):
    c = Counter(b for _, b in groups[cls])
    ties = {b: n for b, n in sorted(c.items()) if n > 1}
    if ties:
        print("ties", cls, ties)
